304		return fmt.Sprintf("snapshot %q entry %q references content %s but records size %d; the content is %d bytes",
305			e.snapshot, e.artifact, e.digest, e.recorded, e.actual)
306	}
307	
308	// validateSnapshotRecord validates one embedded snapshot the same way restore
309	// and gc validate on-disk snapshots.
310	func validateSnapshotRecord(scope string, snap Snapshot) error {
311		if err := validateName(snap.Name); err != nil {
312			return fmt.Errorf("invalid package: %s snapshot name %q is not a legal snapshot name", scope, snap.Name)
313		}
