1	package vault
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12	)
13	
14	// GCCandidate is a content object no longer referenced by the current name
15	// mapping or any snapshot, and therefore eligible for deletion.
16	type GCCandidate struct {
17		Digest string
18		Size   int64
19	}
20	
21	// GCReport summarizes one garbage collection pass. Candidates is always the
22	// full set of unreferenced objects found, sorted by digest; Deleted and Bytes
23	// record what was actually removed (zero for a dry run).
24	type GCReport struct {
25		Candidates []GCCandidate
26		Deleted    int
27		Bytes      int64
28	}
29	
30	// GC removes content objects that neither the current name mapping nor any
31	// saved snapshot still references. With dryRun set, nothing is deleted and
32	// the report only lists the candidates. The whole pass runs under the
33	// exclusive repository lock, so it always observes a complete, quiescent
34	// state: concurrent uploads, snapshot operations, downloads, and verifies
35	// either finish before the pass starts or wait until it is done.
36	//
37	// GC never creates or initializes a repository, never rewrites the index or
38	// any snapshot, and only ever deletes regular files directly inside objects/
39	// whose names are valid digests. Any unreadable or malformed reference
40	// (index or snapshot) aborts the pass before anything is deleted. If a
41	// deletion fails, the pass stops immediately; objects already removed stay
42	// removed and the rest remain as candidates for the next run.
43	func (s *Store) GC(dryRun bool) (GCReport, error) {
44		if strings.TrimSpace(s.root) == "" {
45			return GCReport{}, errors.New("root is required")
46		}
47		// withLock would create a missing root for mutating operations; GC must
48		// refuse an absent or uninitialized repository instead.
49		info, err := os.Stat(s.root)
50		switch {
51		case errors.Is(err, os.ErrNotExist):
52			return GCReport{}, fmt.Errorf("repository %q does not exist; run init first", s.root)
53		case err != nil:
54			return GCReport{}, err
55		case !info.IsDir():
56			return GCReport{}, fmt.Errorf("repository root %q is not a directory", s.root)
57		}
58		var report GCReport
59		err = s.withLock(true, func() error {
60			var gcErr error
61			report, gcErr = s.gcLocked(dryRun)
62			return gcErr
63		})
64		return report, err
65	}
66	
67	func (s *Store) gcLocked(dryRun bool) (GCReport, error) {
68		referenced, err := s.collectReferences()
69		if err != nil {
70			return GCReport{}, err
71		}
72		objectsDir := filepath.Join(s.root, "objects")
73		info, err := os.Lstat(objectsDir)
74		if err != nil {
75			return GCReport{}, fmt.Errorf("cannot inspect objects directory: %w", err)
76		}
77		if info.Mode()&os.ModeSymlink != 0 {
78			return GCReport{}, fmt.Errorf("objects path %q is a symbolic link", objectsDir)
79		}
80		if !info.IsDir() {
81			return GCReport{}, fmt.Errorf("objects path %q is not a directory", objectsDir)
82		}
83		dirents, err := os.ReadDir(objectsDir)
84		if err != nil {
85			return GCReport{}, fmt.Errorf("cannot read objects directory: %w", err)
86		}
87		candidates := []GCCandidate{}
88		for _, dirent := range dirents {
89			// Only regular files named by a valid digest are collectable;
90			// temp files, other names, subdirectories, and symlinks stay.
91			if !dirent.Type().IsRegular() || !isDigest(dirent.Name()) {
92				continue
93			}
94			if _, ok := referenced[dirent.Name()]; ok {
95				continue
96			}
97			fi, err := dirent.Info()
98			if err != nil {
99				return GCReport{}, fmt.Errorf("cannot stat object %q: %w", dirent.Name(), err)
100			}
101			candidates = append(candidates, GCCandidate{Digest: dirent.Name(), Size: fi.Size()})
102		}
103		sort.Slice(candidates, func(i, j int) bool { return candidates[i].Digest < candidates[j].Digest })
