141	// writePackage stages the snapshot package as a complete temporary file
142	// inside the pinned parent directory and commits it via Store.commitOutput,
143	// which revalidates the destination immediately before the atomic rename. The
144	// document is streamed to the temporary file while each referenced object is
145	// verified, so neither object content nor the package text is ever held in
146	// memory. On any failure the temporary file is removed and an existing output
147	// is never touched. It returns the number of carried objects.
148	func (s *Store) writePackage(pin *parentPin, absOut string, mode os.FileMode, name string, target Snapshot, base *Snapshot, carry map[string]struct{}) (int, error) {
149		tmp, tmpBase, err := createTempIn(pin, ".package-")
150		if err != nil {
151			return 0, fmt.Errorf("cannot create temporary file for output: %w", err)
152		}
153		committed := false
154		defer func() {
155			if !committed {
156				removeTempIn(pin, tmpBase)
157			}
158		}()
159		if err := tmp.Chmod(mode); err != nil {
160			tmp.Close()
161			return 0, fmt.Errorf("cannot prepare output file: %w", err)
162		}
163		objects, err := s.streamPackage(tmp, absOut, name, target, base, carry)
164		if err != nil {
165			tmp.Close()
166			return 0, err
167		}
168		if err := tmp.Sync(); err != nil {
169			tmp.Close()
170			return 0, fmt.Errorf("cannot write output %q: %w", absOut, err)
171		}
172		if err := tmp.Close(); err != nil {
173			return 0, fmt.Errorf("cannot write output %q: %w", absOut, err)
174		}
175		if err := s.commitOutput(pin, tmpBase, absOut); err != nil {
176			return 0, err
177		}
178		committed = true
179		_ = syncDirectory(pin.f)
180		return objects, nil
181	}
182	
183	// streamPackage writes the snapshot package to out as one indented JSON
184	// document, byte-identical to marshalPackage over the equivalent in-memory
185	// representation, while reading every referenced object exactly once in
186	// chunks. Objects in the carry set are base64-encoded into the document as
187	// they are verified; objects the delta omits are verified with the same
188	// strictness without being written. Content is never buffered, so memory use
189	// stays independent of object and package size. It returns the number of
190	// carried objects.
191	func (s *Store) streamPackage(out *os.File, absOut, name string, target Snapshot, base *Snapshot, carry map[string]struct{}) (int, error) {
192		snapshotJSON, err := json.MarshalIndent(target, "  ", "  ")
193		if err != nil {
194			return 0, err
195		}
196		var baseJSON []byte
197		if base != nil {
198			baseJSON, err = json.MarshalIndent(*base, "  ", "  ")
199			if err != nil {
200				return 0, err
201			}
202		}
203	
204		w := bufio.NewWriter(out)
205		ew := &errWriter{w: w}
206		ew.writeString("{\n  \"format\": ")
207		ew.writeString(jsonString(packageFormat))
208		fmt.Fprintf(ew, ",\n  \"version\": %d,\n  \"snapshot\": ", packageVersion)
209		ew.Write(snapshotJSON)
210		if base != nil {
211			ew.writeString(",\n  \"base\": ")
212			ew.Write(baseJSON)
213		}
214		ew.writeString(",\n  \"objects\": [")
215	
216		objects := 0
217		for _, digest := range sortedDigests(target.Entries) {
218			if _, carried := carry[digest]; !carried {
219				// Omitted from a delta package: verified in full, not carried.
220				if _, err := s.streamVerifiedObject(digest, target.Entries, nil); err != nil {
221					return 0, fmt.Errorf("snapshot %q references unusable object %s: %w", name, digest, err)
222				}
223				continue
224			}
225			if ew.err != nil {
226				return 0, fmt.Errorf("cannot write output %q: %w", absOut, ew.err)
227			}
228			if objects > 0 {
229				ew.writeString(",")
230			}
231			// The size field precedes the data, so the recorded size is written
232			// before the content is measured; streamVerifiedObject then confirms
233			// the actual byte count against every referencing record before
234			// anything is committed, so a lying record still fails the export.
235			fmt.Fprintf(ew, "\n    {\n      \"digest\": \"%s\",\n      \"size\": %d,\n      \"data\": \"",
236				digest, recordedSize(target.Entries, digest))
237			enc := base64.NewEncoder(base64.StdEncoding, ew)
238			_, verr := s.streamVerifiedObject(digest, target.Entries, enc)
239			cerr := enc.Close()
240			if ew.err != nil {
241				return 0, fmt.Errorf("cannot write output %q: %w", absOut, ew.err)
242			}
243			if verr != nil {
244				return 0, fmt.Errorf("snapshot %q references unusable object %s: %w", name, digest, verr)
245			}
246			if cerr != nil {
247				return 0, fmt.Errorf("cannot write output %q: %w", absOut, cerr)
248			}
249			ew.writeString("\"\n    }")
250			objects++
251		}
252		if objects > 0 {
253			ew.writeString("\n  ")
254		}
255		ew.writeString("]\n}\n")
256		if ew.err != nil {
257			return 0, fmt.Errorf("cannot write output %q: %w", absOut, ew.err)
258		}
259		if err := w.Flush(); err != nil {
260			return 0, fmt.Errorf("cannot write output %q: %w", absOut, err)
261		}
262		return objects, nil
263	}
264	
265	// errWriter records the first write error so the streaming writer can report
266	// an output failure instead of mistaking it for object corruption.
267	type errWriter struct {
268		w   *bufio.Writer
269		err error
270	}
271	
272	func (ew *errWriter) Write(p []byte) (int, error) {
273		if ew.err != nil {
274			return 0, ew.err
275		}
276		n, err := ew.w.Write(p)
277		if err != nil {
278			ew.err = err
279		}
280		return n, err
281	}
282	
283	func (ew *errWriter) writeString(s string) {
284		if ew.err != nil {
285			return
286		}
287		if _, err := ew.w.WriteString(s); err != nil {
288			ew.err = err
289		}
290	}
