```go
package vault

import (
    "os"
    "path/filepath"
    "strings"
    "testing"
)

func TestSnapshotRecordEntriesCaseVariantsAreCorrupt(t *testing.T) {
    goodDigest := digestOf("keep me")
    rec := validRecordJSON("keep.txt", goodDigest, 7)
    cases := map[string]struct {
        record    string  // fields after the name field
        wantField string
    }{...}
    for label, tc := range cases {
        t.Run(label, func(t *testing.T) {
            root := filepath.Join(t.TempDir(), "vault")
            store := New(root)
            if _, err := store.Put("keep.txt", writeInput(t, []byte("keep me"))); err != nil { t.Fatal(err) }
            if _, err := store.CreateSnapshot("good"); err != nil { t.Fatal(err) }
            // genuinely unreferenced object
            extra := []byte("extra unreferenced content")
            if _, err := store.Put("extra.txt", writeInput(t, extra)); err != nil { t.Fatal(err) }
            extraObject := objectPathOf(root, extra)
            if err := store.RestoreSnapshot("good"); err != nil { t.Fatal(err) }  // mapping back to keep.txt only; extra object unreferenced

            record := `{"name":"releases/corrupt",` + tc.record + `}`
            recordPath := filepath.Join(root, "snapshots", "releases", "corrupt.json")
            if err := os.MkdirAll(filepath.Dir(recordPath), 0o755); err != nil { t.Fatal(err) }
            if err := os.WriteFile(recordPath, []byte(record), 0o644); err != nil { t.Fatal(err) }

            assertCorrupt := func(op string, err error) {
                t.Helper()
                if err == nil { t.Fatalf("%s succeeded over a corrupt snapshot record", op) }
                msg := err.Error()
                if !strings.Contains(msg, `snapshot "releases/corrupt" is corrupted`) {
                    t.Fatalf("%s error %q does not identify the corrupt snapshot by its full name", op, msg)
                }
                if !strings.Contains(msg, tc.wantField) {
                    t.Fatalf("%s error %q does not name the offending field %s", op, msg, tc.wantField)
                }
            }

            // Restore: fails, current mapping unchanged.
            assertCorrupt("restore", store.RestoreSnapshot("releases/corrupt"))
            entries, err := store.List()
            if err != nil || len(entries) != 1 || entries[0].Name != "keep.txt" {
                t.Fatalf("restore failure changed the current mapping: entries=%+v err=%v", entries, err)
            }

            // List: fails, no partial list.
            infos, err := store.ListSnapshots()
            assertCorrupt("list snapshots", err)
            if infos != nil { t.Fatalf("list returned partial snapshots: %+v", infos) }

            // Export: fails, no package created; existing output untouched.
            output := filepath.Join(t.TempDir(), "pkg.json")
            assertCorrupt("export", func() error { _, err := store.ExportSnapshot("releases/corrupt", "", output); return err }())
            if _, err := os.Stat(output); !os.IsNotExist(err) {
                t.Fatalf("failed export created a package: %v", err)
            }
            existing := filepath.Join(t.TempDir(), "existing.json")
            if err := os.WriteFile(existing, []byte("previous output"), 0o640); err != nil { t.Fatal(err) }
            assertCorrupt("export over existing output", func() error { _, err := store.ExportSnapshot("releases/corrupt", "", existing); return err }())
            got, err := os.ReadFile(existing)
            if err != nil || string(got) != "previous output" { ... }
            info, _ := os.Stat(existing); if info.Mode().Perm() != 0o640 { ... }

            // Incremental export using the corrupt snapshot as its base also fails.
            deltaOut := filepath.Join(t.TempDir(), "delta.json")
            assertCorrupt("incremental export", func() error { _, err := store.ExportSnapshot("good", "releases/corrupt", deltaOut); return err }())
            if _, err := os.Stat(deltaOut); !os.IsNotExist(err) { ... }

            // GC, dry run and real: both fail before deleting anything.
            if _, err := store.GC(true); err == nil { t.Fatal("dry-run gc succeeded over a corrupt snapshot record") }
            assertCorrupt("gc", func() error { _, err := store.GC(false); return err }())
            if got, err := os.ReadFile(extraObject); err != nil || string(got) != string(extra) {
                t.Fatalf("gc touched the unreferenced object: content=%q err=%v", got, err)
            }

            // The corrupt record bytes are preserved exactly.
            got, err = os.ReadFile(recordPath)
            if err != nil || string(got) != record { ... }
        })
    }
}
```

