	if err != nil {
		t.Fatal(err)
	}
	if len(entries) != len(contents) {
		t.Fatalf("entries=%+v", entries)
	}
	for name, content := range contents {
		out := filepath.Join(t.TempDir(), "out.bin")
		if err := store.Get(name, out); err != nil {
			t.Fatalf("get %q: %v", name, err)
